// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint256 fuzz) public {
        if (fuzz == type(uint256).max) {
            fuzz = 0;
        }

        bool ok;
        try c.version() returns (string memory v) {
            ok = bytes(v).length != 0;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
